'use strict';
/* Admin console and platform services (M-PLT): users, roles, org, approval rules, settings, templates, lookups, integrations, data administration, audit log */

const PERM_DOC = { 'admin.users': 'Manage users, roles and departments', 'admin.config': 'Change configuration, numbering and templates', 'data.admin': 'Bulk import, export, merge and restore records', 'audit.view': 'View and export the audit log', integrations: 'Manage integrations', export: 'Export lists and reports', 'read.all': 'Read every record in the company', 'approve.any': 'Approve high-value and final-stage items', 'approve.team': 'Approve the team’s requests', 'approve.hr': 'Approve HR items', 'chat.announce': 'Post company-wide announcements', 'period.reopen': 'Reopen a closed accounting period', 'multi.co': 'Switch between companies', 'task.manage': 'Manage everyone’s tasks', 'perf.manage': 'Manage KPIs and appraisals', 'learn.manage': 'Run Learning and Development', 'hr.sensitive': 'See salary, ID and disciplinary records', 'hr.write': 'Edit HR records', 'announce.post': 'Post HR announcements', 'rpt.review': 'Review departmental reports', 'fin.confirm': 'Confirm client payments', 'fin.confirm2': 'Act as second confirming officer', 'fin.invoice': 'Raise invoices', 'fin.expense.post': 'Disburse expenses', 'fin.commission.pay': 'Pay commissions', 'acc.journal': 'Post journals', 'acc.close': 'Close accounting periods' };
const MOD_DOC = { dashboard: 'Dashboard', mywork: 'My work', admin: 'Admin console', chat: 'Team chat', learning: 'Learning', inventory: 'Property inventory', crm: 'Sales and CRM', realtors: 'Realtors', cx: 'Customer experience', finance: 'Finance', accounting: 'Accounting', hr: 'HR', performance: 'Performance', work: 'Tasks and projects', reports: 'Department reports' };
function applyRoleOverrides() { (DB.d.roles || []).forEach(r => { if (ROLES[r.id]) { if (r.mods) ROLES[r.id].mods = r.mods; if (r.perms) ROLES[r.id].perms = r.perms; } }); }
const admFull = () => can('admin.users') || can('admin.config');
const ADM_TABS = () => admFull() ? [{ k: 'users', l: 'Users' }, { k: 'roles', l: 'Roles and permissions' }, { k: 'departments', l: 'Departments' }, { k: 'companies', l: 'Companies' }, { k: 'rules', l: 'Approval chains' }, { k: 'numbering', l: 'Numbering sequences' }, { k: 'settings', l: 'Settings' }, { k: 'templates', l: 'Document templates' }, { k: 'lookups', l: 'Lookup lists' }, { k: 'integrations', l: 'Integrations' }, { k: 'data', l: 'Data administration' }, { k: 'chat', l: 'Chat administration' }, { k: 'audit', l: 'Audit log' }, { k: 'design', l: 'Design system' }, { k: 'flows', l: 'Prototype flows' }] : [{ k: 'audit', l: 'Audit log' }, { k: 'integrations', l: 'Integrations' }, { k: 'flows', l: 'Prototype flows' }];

PAGES.admin = (parts, q) => {
  const tl = ADM_TABS(); const tab = parts[0] && tl.find(t => t.k === parts[0]) ? parts[0] : tl[0].k; let body = '';
  if (tab === 'users') body = admUsers(); else if (tab === 'roles') body = admRoles(); else if (tab === 'departments') body = admDepts(); else if (tab === 'companies') body = admCompanies(); else if (tab === 'numbering') body = admNumbering(); else if (tab === 'design') body = admDesign(); else if (tab === 'flows') body = admFlows(); else if (tab === 'rules') body = admRules(); else if (tab === 'settings') body = admSettings(); else if (tab === 'templates') body = admTemplates(); else if (tab === 'lookups') body = admLookups(); else if (tab === 'integrations') body = admIntegrations(); else if (tab === 'data') body = admData(); else if (tab === 'chat') body = admChat(); else if (tab === 'audit') body = admAudit();
  return pageHead({ title: `Admin${pi('settings', true)}console`, sub: ROLES[me().role].label + ' · configuration is changed here, without code changes' }) + tabs('admin', tl, tab) + body;
};

/* ----- users & roles ----- */
function admUsers() {
  const rows = () => DB.d.users.filter(u => can('multi.co') || u.co.includes(CO)).map(u => ({ ...u, roleLabel: ROLES[u.role]?.label || u.role, mgr: userName(u.manager), cos: u.co.map(c => DB.get('companies', c)?.short).join(', ') }));
  return table({ id: 'users', title: 'Users', rows, ph: 'Search users', sort: { k: 'name', dir: 1 }, filters: [{ k: 'role', l: 'Role', o: Object.entries(ROLES).map(([k, v]) => [k, v.label]), get: u => u.role }, { k: 'dept', l: 'Department', o: uniq(DB.d.users.map(u => u.dept)), get: u => u.dept }], onRow: u => editUser(u.id), tools: can('admin.users') ? `<button class="btn sm primary" data-act="user.new">${icon('plus', 'sm')} New user</button>` : '', cols: [{ k: 'name', l: 'User', r: u => `<div class="row">${avatar(u.name, 'sm')}<div class="cellmain"><b>${esc(u.name)}</b><span>${esc(u.email)}</span></div></div>`, x: u => u.name }, { k: 'roleLabel', l: 'Role' }, { k: 'dept', l: 'Dept' }, { k: 'mgr', l: 'Manager' }, { k: 'cos', l: 'Companies' }, { k: 'tfa', l: '2FA', r: u => ROLES[u.role]?.tfa ? spill('Required', 'ok') : '<span class="muted">Optional</span>', x: u => ROLES[u.role]?.tfa ? 'Required' : 'Optional' }, { k: 'off', l: 'Status', r: u => spill(u.off ? 'Disabled' : 'Active', u.off ? 'bad' : 'ok'), x: u => u.off ? 'Disabled' : 'Active' }] });
}
const userFields = () => [{ n: 'name', l: 'Full name', req: true }, { n: 'email', l: 'Email', t: 'email', req: true, half: true }, { n: 'phone', l: 'Phone', t: 'tel', half: true }, { n: 'role', l: 'Role', t: 'select', req: true, blank: false, o: Object.entries(ROLES).map(([k, v]) => [k, v.label]), half: true }, { n: 'dept', l: 'Department', t: 'select', o: uniq(DB.q('depts').map(d => d.name).concat(['IT', 'Audit'])), half: true }, { n: 'title', l: 'Job title', half: true }, { n: 'manager', l: 'Line manager', t: 'select', o: coUsers().map(u => [u.id, u.name]), blank: 'None', half: true }, { n: 'co', l: 'Companies', t: 'multi', o: DB.d.companies.map(c => [c.id, c.name]), req: true }, { n: 'flags', l: 'Special responsibilities', t: 'multi', o: [['opsdirector', 'Operations Director (approves commissions and transfers)'], ['tarpadmin', 'TARP Admin (approves Form C and induction)'], ['rlt.write', 'Realtors Development write'], ['rlt.campaign', 'Manage campaigns']] }, { n: 'expires', l: 'Access ends on (for time-limited auditors)', t: 'date' }, { n: 'off', l: 'Disabled (cannot sign in)', t: 'check' }];
ACT['user.new'] = () => openForm({ title: 'New user', fields: userFields(), vals: { role: 'staff', co: [CO] }, wide: true, onSubmit: v => { if (DB.d.users.some(u => u.email === v.email)) { toast('That email is already in use.', 'bad'); return false; } const id = 'u_' + rid(); DB.d.users.push({ id, ...v, prefs: { email: true, sms: false, app: true } }); audit('create', 'users', id, v.name + ' · ' + v.role); DB.dirty(); render(); } });
function editUser(id) { const u = userById(id); if (!can('admin.users')) return; openForm({ title: 'Edit user', fields: userFields(), vals: u, wide: true, onSubmit: v => { if (id === SESS.uid && (v.off || v.role !== u.role)) { toast('You cannot change your own role or disable yourself.', 'bad'); return false; } DB.set('users', id, v, { action: 'user-update' }); if (v.off) DB.d.channels.forEach(c => { if (c.members?.includes(id) && c.type !== 'public') c.members = c.members.filter(m => m !== id); }); render(); } }); }
function admRoles() {
  const roles = Object.entries(ROLES); const perms = Object.keys(PERM_DOC); const mods = Object.entries(MOD_DOC);
  const has = (r, m) => r.mods === 'all' ? true : r.mods.some(x => x === m || x.startsWith(m + ':'));
  const cell = ok => ok ? `<span style="color:var(--forest)">${icon('check', 'sm')}</span>` : '<span class="muted">·</span>';
  return `<div class="alert info" style="margin-bottom:14px">${icon('shield', 'sm')}<span>Access is scoped by company, then department, then record. This matrix shows what each role can open and do. Select Edit on a role to change it without code changes. Salary, ID and disciplinary records stay restricted to HR and executives regardless of module access. External realtors have no Tri-OP login; they use the Tri-Pay realtor app.</span></div>
  ${card('Modules by role', `<div class="scroll-x"><table class="tbl"><thead><tr><th>Module</th>${roles.map(([k, r]) => `<th class="num">${esc(r.label)}</th>`).join('')}</tr></thead><tbody>${mods.map(([m, l]) => `<tr><td>${esc(l)}</td>${roles.map(([k, r]) => `<td class="num">${cell(has(r, m))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`, { ic: 'grid' })}
  <div style="margin-top:16px">${card('Permissions by role', `<div class="scroll-x"><table class="tbl"><thead><tr><th>Permission</th>${roles.map(([k, r]) => `<th class="num">${esc(r.label)}</th>`).join('')}</tr></thead><tbody>${perms.map(p => `<tr><td><b style="font-weight:500">${esc(p)}</b><div class="small muted">${esc(PERM_DOC[p])}</div></td>${roles.map(([k, r]) => `<td class="num">${cell(r.perms.includes(p))}</td>`).join('')}</tr>`).join('')}<tr><td>Sign-in</td>${roles.map(([k, r]) => `<td class="num small">${r.tfa ? '2FA' : 'Login'}</td>`).join('')}</tr><tr><td>Scope</td>${roles.map(([k, r]) => `<td class="num small">${esc(r.scope)}</td>`).join('')}</tr></tbody></table></div>`, { ic: 'key' })}</div>
  <div class="row wrap" style="margin-top:14px">${can('admin.users') ? roles.map(([k, r]) => `<button class="btn sm" data-act="role.edit" data-id="${k}">Edit ${esc(r.label)}</button>`).join('') : ''}</div>`;
}
ACT['role.edit'] = el => { const k = el.dataset.id; const r = ROLES[k]; openForm({ title: 'Edit role · ' + esc(r.label), wide: true, vals: { mods: r.mods === 'all' ? Object.keys(MOD_DOC) : r.mods.filter(m => !m.includes(':')), perms: r.perms }, fields: [{ n: 'mods', l: 'Modules (full access)', t: 'multi', o: Object.entries(MOD_DOC) }, { n: 'perms', l: 'Permissions', t: 'multi', o: Object.entries(PERM_DOC).map(([p, d]) => [p, p + ' · ' + d]) }], onSubmit: v => { const mods = r.mods === 'all' && v.mods.length === Object.keys(MOD_DOC).length ? 'all' : (r.mods === 'all' ? v.mods : v.mods.concat(r.mods.filter(m => m.includes(':')))); const rec = DB.d.roles.find(x => x.id === k); if (rec) { rec.mods = mods; rec.perms = v.perms; } applyRoleOverrides(); audit('config', 'roles', k, 'Role permissions changed'); DB.dirty(); toast('Role updated'); render(); } }); };

/* ----- org ----- */
function admDepts() { return admOrg(true); }
function admCompanies() { return admOrg(false); }
function admOrg(deptOnly) {
  const dT = table({ id: 'depts', title: 'Departments', rows: () => DB.q('depts').map(d => ({ ...d, headName: userName(d.head), n: coUsers().filter(u => u.dept === d.name).length })), export: false, tools: can('admin.users') ? `<button class="btn sm primary" data-act="dept.new">Add department</button>` : '', onRow: d => can('admin.users') ? editDept(d.id) : null, cols: [{ k: 'name', l: 'Department' }, { k: 'headName', l: 'Head' }, { k: 'n', l: 'People', num: true }] }); const cT = table({ id: 'cos', title: 'Companies', rows: () => DB.d.companies, export: false, tools: can('admin.users') && can('multi.co') ? '' : '', cols: [{ k: 'name', l: 'Company' }, { k: 'short', l: 'Code' }, { k: 'fyStart', l: 'Financial year', r: c => '1 July – 30 June' }, { k: 'currency', l: 'Currency', r: c => 'NGN (base)' }] });
  if (deptOnly) return dT + '<p class="small muted" style="margin-top:10px">Department channels in Team chat are created from this list.</p>';
  return cT + `<p class="small muted" style="margin-top:10px">Each company has its own chart of accounts, settings, numbering and data. Naira is the base currency; the data model keeps a currency on each company so multi-currency can be added later.</p>${can('admin.users') ? `<div style="margin-top:12px"><button class="btn" data-act="co.new">${icon('plus', 'sm')} Add a Triconna Group company</button></div>` : ''}`;
}
ACT['dept.new'] = () => openForm({ title: 'Add department', fields: [{ n: 'name', l: 'Name', req: true }, { n: 'head', l: 'Head', t: 'select', o: coUsers().map(u => [u.id, u.name]) }], onSubmit: v => { DB.add('depts', v); render(); } });
function editDept(id) { const d = DB.get('depts', id); openForm({ title: 'Edit department', vals: d, fields: [{ n: 'name', l: 'Name', req: true }, { n: 'head', l: 'Head', t: 'select', o: coUsers().map(u => [u.id, u.name]) }], onSubmit: v => { DB.set('depts', id, v); render(); } }); }
ACT['co.new'] = () => openForm({ title: 'Add company', fields: [{ n: 'name', l: 'Company name', req: true }, { n: 'short', l: 'Short code', req: true, vf: v => DB.d.companies.some(c => c.id === v.toLowerCase()) ? 'Code already used.' : '' }, { n: 'address', l: 'Address' }], hint: '', onSubmit: v => { const id = v.short.toLowerCase(); DB.d.companies.push({ id, name: v.name, short: v.short.toUpperCase(), address: v.address || '', fyStart: '07-01', currency: 'NGN' }); const keep = CO; seedCompanyBase(id); CO = keep; DB.d.users.filter(u => u.role === 'groupexec' || u.role === 'superadmin').forEach(u => { if (!u.co.includes(id)) u.co.push(id); }); audit('create', 'companies', id, v.name); DB.dirty(); toast('Company added. Switch to it from the company menu.'); render(); } });

/* ----- approval rules (PLT-01) ----- */
function admRules() {
  return `<div class="alert info" style="margin-bottom:14px">${icon('shield', 'sm')}<span>Multi-step approval chains are set per document type and amount band. Each approver must be a different person from the requester. When an approver is on leave or has delegated, their delegate can act.</span></div>` + table({ id: 'rules', title: 'Approval rules', export: false, rows: () => DB.q('rules'), tools: can('admin.config') ? `<button class="btn sm primary" data-act="rule.new">${icon('plus', 'sm')} New chain</button>` : '', cols: [{ k: 'type', l: 'Document', r: r => esc(APPROVAL_LABEL[r.type] || r.type), x: r => r.type }, { k: 'tiers', l: 'Amount bands and chain', r: r => r.tiers.map(t => `<div class="row" style="margin:3px 0"><span class="tag">${t.max == null ? 'Above' : 'Up to ' + moneyShort(t.max)}</span> ${t.steps.map(s => spill(STEP_LABEL[s] || s, 'mute')).join('<span class="muted">›</span>') || '<span class="muted">Auto-approved</span>'}</div>`).join(''), x: r => r.tiers.map(t => (t.max ?? 'above') + ':' + t.steps.join('>')).join(' | ') }, { k: 'a', l: '', r: r => can('admin.config') ? `<button class="btn sm" data-act="rule.edit" data-id="${r.id}">Edit</button>` : '', x: () => '' }] });
}

/* ----- settings & numbering (PLT-05) ----- */
function admSettings() {
  const S = k => DB.setting(k); const c = S('commissionRates'); const sla = S('slaHours');
  const fields = [{ n: 'reservationDays', l: 'Reservation hold (days) without a confirmed deposit', t: 'number', min: 1, half: true }, { n: 'secondApprovalAmount', l: 'Payments at or above this need a second officer (₦)', t: 'money', half: true }, { n: 'lateTime', l: 'Resumption time (lateness is measured from here)', t: 'time', half: true }, { n: 'staleLeadHours', l: 'Reassign untouched leads after (hours)', t: 'number', half: true }, { n: 'followupHours', l: 'Collections follow-up target (hours)', t: 'number', half: true }, { n: 'realtorStallDays', l: 'Realtor stalls after (days without activity)', t: 'number', half: true }, { n: 'protectionDays', l: 'Realtor lead protection window (days)', t: 'number', half: true }, { n: 'assignRule', l: 'Lead assignment rule', t: 'select', blank: false, o: [['round-robin', 'Round-robin'], ['estate', 'By estate'], ['realtor', 'By realtor']], half: true }, { n: 'vatRate', l: 'VAT rate (%)', t: 'number', step: 'any', half: true }, { n: 'whtRate', l: 'WHT rate (%)', t: 'number', step: 'any', half: true }, { n: 'cr_a', l: 'Associate commission (%)', t: 'number', step: 'any', half: true }, { n: 'cr_m', l: 'Maverick commission (%)', t: 'number', step: 'any', half: true }, { n: 'cr_r', l: 'Referral commission (%)', t: 'number', step: 'any', half: true }, { n: 'officeIp', l: 'Office network (for Office clock-ins)', half: true }, { n: 'retentionDays', l: 'Chat retention (days)', t: 'number', half: true }];
  const vals = { reservationDays: S('reservationDays'), secondApprovalAmount: S('secondApprovalAmount'), lateTime: S('lateTime'), staleLeadHours: S('staleLeadHours'), followupHours: S('followupHours'), realtorStallDays: S('realtorStallDays'), protectionDays: S('protectionDays'), assignRule: S('assignRule') || 'round-robin', vatRate: S('vatRate'), whtRate: S('whtRate'), cr_a: c.Associate, cr_m: c.Maverick, cr_r: c.Referral, officeIp: S('officeIp'), retentionDays: S('retentionDays') };
  const seqs = Object.entries(DB.d.seq || {}).filter(([k]) => k.startsWith(CO + ':')).map(([k, v]) => ({ id: k, name: k.split(':')[1], v }));
  return `<div class="grid g2" style="align-items:start">${card('Settings for ' + esc(company().name), `<div id="setform">${formHtml(fields, vals, 'st')}</div><div class="row" style="margin-top:14px"><button class="btn primary" data-act="set.save">Save settings</button></div><p class="small muted" style="margin-top:8px">Settings are per company. Commission rates are placeholders until the Commission Distribution Policy (TR-POL-COM-001) values are loaded.</p>`, { ic: 'settings' })}<div class="stack">${card('Numbering sequences', table({ id: 'seqs', title: 'Numbering', rows: () => seqs, export: false, ps: 20, cols: [{ k: 'name', l: 'Sequence', r: s => ({ sale: 'Sales (SL-yyyy-nnnn)', receipt: 'Receipts (RC-yyyy-nnnnn)', invoice: 'Invoices (INV-nnnn)', journal: 'Journals (JV-yyyy-nnnn)', ticket: 'Tickets (TK-nnnn)', expense: 'Expenses (EX-nnnn)', bill: 'Bills (BL-nnnn)', asset: 'Assets (AST-nnn)' }[s.name] || esc(s.name)) }, { k: 'v', l: 'Last used', num: true }, { k: 'a', l: '', r: s => can('admin.config') ? `<button class="btn sm" data-act="seq.edit" data-id="${esc(s.id)}">Set</button>` : '' }] }), { ic: 'tag' })}${schedulesCard()}${card('SLA hours', `<div class="row wrap">${['Urgent', 'High', 'Medium', 'Low'].map(p => `<span class="tag">${p}: ${sla[p]} h</span>`).join('')}</div><p class="small muted" style="margin-top:8px">Edit these on Customer experience → SLA.</p>`, { ic: 'clock' })}</div></div>`;
}
ACT['set.save'] = () => { const f = [{ n: 'reservationDays', t: 'number' }, { n: 'secondApprovalAmount', t: 'money' }, { n: 'lateTime' }, { n: 'staleLeadHours', t: 'number' }, { n: 'followupHours', t: 'number' }, { n: 'realtorStallDays', t: 'number' }, { n: 'protectionDays', t: 'number' }, { n: 'assignRule' }, { n: 'vatRate', t: 'number' }, { n: 'whtRate', t: 'number' }, { n: 'cr_a', t: 'number' }, { n: 'cr_m', t: 'number' }, { n: 'cr_r', t: 'number' }, { n: 'officeIp' }, { n: 'retentionDays', t: 'number' }]; const v = readForm($('#setform'), f, true); if (!can('admin.config')) return toast('Only an administrator can change settings.', 'bad'); ['reservationDays', 'secondApprovalAmount', 'lateTime', 'staleLeadHours', 'followupHours', 'realtorStallDays', 'protectionDays', 'assignRule', 'vatRate', 'whtRate', 'officeIp', 'retentionDays'].forEach(k => { if (v[k] !== '' && v[k] != null) DB.setSetting(k, v[k]); }); DB.setSetting('commissionRates', { Associate: v.cr_a, Maverick: v.cr_m, Referral: v.cr_r }); toast('Settings saved for ' + company().name); render(); };
ACT['seq.edit'] = el => openForm({ title: 'Set last used number', fields: [{ n: 'v', l: 'Last used', t: 'number', min: 0, req: true }], vals: { v: DB.d.seq[el.dataset.id] }, onSubmit: v => { DB.d.seq[el.dataset.id] = v.v; audit('config', 'numbering', el.dataset.id, 'Set to ' + v.v); DB.dirty(); render(); } });

/* ----- templates (PLT-03) ----- */
function admTemplates() {
  return `<div class="alert info" style="margin-bottom:14px">${icon('file', 'sm')}<span>Branded documents (offer letters, allocation letters, receipts) are generated from these templates as PDF with a QR code to verify them. Use placeholders such as <code>{{client.name}}</code>, <code>{{plotsText}}</code>, <code>{{sale.totalF}}</code>, <code>{{payment.amountF}}</code>.</span></div>` + table({ id: 'tpl', title: 'Templates', rows: () => DB.q('templates'), export: false, onRow: t => editTemplate(t.id), cols: [{ k: 'name', l: 'Template' }, { k: 'type', l: 'Type', r: t => `<span class="tag">${esc(t.type)}</span>` }, { k: 'body', l: 'Preview', r: t => `<span class="small muted">${esc(textOf(t.body).slice(0, 90))}…</span>`, x: t => textOf(t.body) }] }) + `<div style="margin-top:14px"><h3 style="font-size:16px;font-weight:500;margin-bottom:8px">Issued documents</h3>${table({ id: 'docs', title: 'Issued documents', rows: () => DB.q('docsLog').slice().sort(by(d => d.ts, -1)), ps: 8, onRow: d => openDoc(d.code), cols: [{ k: 'title', l: 'Document' }, { k: 'client', l: 'Client' }, { k: 'saleNo', l: 'Sale' }, { k: 'code', l: 'Verification code', r: d => `<code>${esc(d.code)}</code>` }, { k: 'ts', l: 'Issued', r: d => fmtDT(d.ts), sv: d => d.ts }] })}</div>`;
}
function editTemplate(id) { if (!can('admin.config')) return; const t = DB.get('templates', id); openForm({ title: 'Edit template · ' + esc(t.name), wide: true, vals: t, fields: [{ n: 'name', l: 'Name', req: true }, { n: 'body', l: 'Body (HTML with {{placeholders}})', t: 'textarea', req: true }, { n: 'pv', t: 'html', html: '<p class="small muted">Preview is shown on the issued document.</p>' }], onSubmit: v => { DB.set('templates', id, { name: v.name, body: v.body }, { action: 'template-change' }); render(); } }); }

/* ----- lookups ----- */
function admLookups() {
  const defs = [['leadStages', 'Lead pipeline stages (keep Won and Lost last)', LEAD_STAGES()], ['leadSources', 'Lead sources', LEAD_SOURCES()]];
  return `<div class="grid g2">${defs.map(([k, l, vals]) => card(esc(l), `<div class="row wrap" style="margin-bottom:10px">${vals.map(v => `<span class="tag">${esc(v)}</span>`).join('')}</div>${can('admin.config') ? `<button class="btn sm" data-act="lk.edit" data-k="${k}">Edit list</button>` : ''}`, { ic: 'list' })).join('')}</div>`;
}
ACT['lk.edit'] = el => { const k = el.dataset.k; const cur = k === 'leadStages' ? LEAD_STAGES() : LEAD_SOURCES(); openForm({ title: 'Edit list', fields: [{ n: 'v', l: 'One value per line', t: 'textarea', req: true, hint: k === 'leadStages' ? 'Won and Lost must remain, last. Losing a lead always needs a reason.' : '' }], vals: { v: cur.join('\n') }, onSubmit: v => { let vals = v.v.split('\n').map(x => x.trim()).filter(Boolean); if (k === 'leadStages') { vals = vals.filter(x => !['Won', 'Lost'].includes(x)).concat(['Won', 'Lost']); } const ex = DB.q('lookups').find(l => l.key === k); if (ex) DB.set('lookups', ex.id, { values: vals }); else DB.add('lookups', { key: k, values: vals }); render(); } }); };

/* ----- integrations ----- */
function admIntegrations() {
  const wh = DB.q('webhooks'); const ob = DB.q('outbox').slice().sort(by(o => o.ts, -1));
  const cards = [['Tri-Pay', 'link', 'Connected (sandbox)', 'ok', `${wh.length} webhooks · single sign-on and embedded screens on`], ['Email', 'mail', 'Connected', 'ok', ob.filter(o => o.channel === 'email').length + ' emails queued or sent'], ['Nigerian SMS gateway', 'phone', 'Connected', 'ok', ob.filter(o => o.channel === 'sms').length + ' SMS queued or sent'], ['Website lead forms', 'globe', 'Live', 'ok', 'Lead form and Form A links on the CRM and Realtors pages'], ['Google Drive archive', 'layers', 'Phase 2', 'warn', 'Retired sheets become a read-only archive in Drive'], ['Biometric attendance device', 'clock', 'Phase 2 (if adopted)', 'warn', 'Import logs from Attendance'], ['WhatsApp Business API', 'chat', 'Phase 3', 'mute', 'Messages are logged now and sent by API later']];
  return `<div class="grid g3" style="margin-bottom:16px">${cards.map(([n, ic, s, t, d]) => card(esc(n), `<div style="margin-bottom:8px">${spill(s, t)}</div><p class="small muted">${esc(d)}</p>`, { ic })).join('')}</div><div class="grid g2" style="align-items:start">${card('Tri-Pay contract', kv([['Environment', 'Sandbox (production at day 60)'], ['Webhook signature', 'HMAC-SHA256, header X-TriPay-Signature'], ['Idempotency', 'Key on every delivery; duplicates ignored'], ['Retries', 'Exponential backoff, 5 attempts'], ['Reconciliation', 'Daily report: Tri-Pay confirmed vs Tri-OP ledger']]) + (can('integrations') ? `<button class="btn sm" style="margin-top:12px" data-act="int.rotate">Rotate webhook secret</button>` : ''), { ic: 'link' })}${card('Open API', `<p class="muted" style="margin-bottom:10px">Tri-Pay and future tools connect through Tri-OP’s documented API.</p><div class="codebox">GET  /api/v1/clients\nGET  /api/v1/plots?estate=&status=\nPOST /api/v1/sales\nPOST /api/v1/payments        (idempotent)\nGET  /api/v1/ledger/journals\nPOST /api/v1/webhooks/tripay (signed)</div><div class="row" style="margin-top:12px"><button class="btn sm" data-act="api.spec">${icon('download', 'sm')} Download OpenAPI description</button>${can('integrations') ? `<button class="btn sm" data-act="api.token">Create API token</button>` : ''}</div>`, { ic: 'bolt' })}</div><div style="margin-top:16px">${table({ id: 'outbox', title: 'Outbound messages', rows: () => ob, ps: 8, filters: [{ k: 'channel', l: 'Channel', o: ['email', 'sms', 'push', 'log'], get: o => o.channel }], cols: [{ k: 'ts', l: 'When', r: o => fmtDT(o.ts), sv: o => o.ts }, { k: 'channel', l: 'Channel', r: o => `<span class="tag">${esc(o.channel)}</span>` }, { k: 'to', l: 'To' }, { k: 'text', l: 'Message' }] })}</div>`;
}
ACT['int.rotate'] = () => confirmDlg('Rotate the Tri-Pay webhook secret? Tri-Pay must be updated with the new secret.', () => { audit('config', 'integrations', 'tripay', 'Webhook secret rotated'); toast('New secret generated and logged'); }, { yes: 'Rotate' });
ACT['api.token'] = () => { const t = 'tri_' + Array.from({ length: 28 }, () => Math.floor(Math.random() * 36).toString(36)).join(''); audit('config', 'integrations', 'api-token', 'API token created'); openModal({ title: 'API token', live: false, body: `<p class="muted" style="margin-bottom:10px">Copy it now. It is shown once.</p><div class="codebox">${t}</div>`, foot: '<button class="btn" data-act="ov.close">Done</button>' }); };
ACT['api.spec'] = () => { const spec = { openapi: '3.0.3', info: { title: 'Tri-OP API', version: '1.0.0', description: 'Documented API of the Tri-OP Management System (contract for the backend phase).' }, paths: Object.fromEntries(['clients', 'plots', 'estates', 'sales', 'payments', 'invoices', 'tickets', 'tasks', 'journals'].flatMap(r => [['/api/v1/' + r, { get: { summary: 'List ' + r, responses: { 200: { description: 'OK' } } }, post: { summary: 'Create ' + r.replace(/s$/, ''), responses: { 201: { description: 'Created' } } } }], ['/api/v1/' + r + '/{id}', { get: { summary: 'Get one', parameters: [{ name: 'id', in: 'path', required: true, schema: { type: 'string' } }], responses: { 200: { description: 'OK' } } } }]])) }; download('tri-op-openapi.json', JSON.stringify(spec, null, 2), 'application/json'); };

/* ----- data administration (PLT-06) ----- */
const num0 = v => { const n = parseFloat(String(v ?? '').replace(/[^\d.-]/g, '')); return isNaN(n) ? 0 : n; };
function integrityChecks() {
  const out = []; const live = DB.q('sales').filter(s => !['revoked', 'expired'].includes(s.status));
  const dbl = DB.q('plots').filter(p => live.filter(s => s.plotIds.includes(p.id)).length > 1); out.push({ k: 'Double allocation: a plot in more than one active sale', items: dbl.map(plotLabel) });
  out.push({ k: 'Sold plots without a client or sale', items: DB.q('plots').filter(p => ['allocated', 'paid', 'documented'].includes(p.status) && (!p.clientId || !activeSaleOfPlot(p.id))).map(plotLabel) });
  out.push({ k: 'Sales paid above their total', items: live.filter(s => s.paid > s.total + 1).map(s => s.no) });
  out.push({ k: 'Sales whose paid amount differs from confirmed payments', items: live.filter(s => !s.migrated && Math.abs(s.paid - sum(DB.q('payments').filter(p => p.saleId === s.id && p.status === 'confirmed'), p => p.amount)) > 1).map(s => s.no) });
  out.push({ k: 'Unbalanced journals', items: DB.q('journals').filter(j => j.status === 'posted' && Math.abs(sum(j.lines, l => l.dr) - sum(j.lines, l => l.cr)) > .01).map(j => j.no) });
  const tb = trialBalance(); out.push({ k: 'Trial balance debits and credits differ', items: Math.abs(sum(tb, a => a.dr) - sum(tb, a => a.cr)) > 1 ? ['Dr ' + money(sum(tb, a => a.dr)) + ' vs Cr ' + money(sum(tb, a => a.cr))] : [] });
  const ph = {}; DB.q('clients').forEach(c => { const k = phoneNorm(c.phone); (ph[k] = ph[k] || []).push(c); }); out.push({ k: 'Duplicate clients (same phone number)', items: Object.values(ph).filter(l => l.length > 1).map(l => l.map(c => c.name).join(' / ')) });
  out.push({ k: 'Confirmed payments without a ledger entry', items: DB.q('payments').filter(p => p.status === 'confirmed' && p.channel !== 'migration' && !DB.q('journals').some(j => j.source === 'payment' && j.ref === p.id)).map(p => p.receiptNo || p.id) });
  out.push({ k: 'Plots with an expired reservation still held', items: DB.q('plots').filter(p => p.status === 'reserved' && p.reservedUntil && p.reservedUntil < today()).map(plotLabel) });
  return out;
}
function admData() {
  const checks = integrityChecks(); const bad = checks.filter(c => c.items.length).length; const bin = []; Object.keys(DB.d).forEach(c => { if (Array.isArray(DB.d[c]) && !['audit'].includes(c)) DB.d[c].filter(r => r.del && (GLOBAL.has(c) || r.co === CO)).forEach(r => bin.push({ id: c + '|' + r.id, c, rid: r.id, name: r.name || r.title || r.no || r.subject || r.text || r.id, at: r.delAt, by: r.delBy })); });
  return `<div class="grid g2" style="align-items:start">${card('Data integrity checks', `<div class="alert ${bad ? '' : 'ok'}" style="margin-bottom:12px">${bad ? icon('warn', 'sm') + `<span>${bad} check(s) need attention.</span>` : icon('check', 'sm') + '<span>All checks passed.</span>'}</div>${checks.map(c => `<div style="padding:6px 0;border-bottom:1px solid #E1ECDF"><div class="row">${c.items.length ? icon('warn', 'sm') : icon('check', 'sm')}<span class="grow">${esc(c.k)}</span><b style="font-weight:500">${c.items.length}</b></div>${c.items.length ? `<div class="small muted" style="padding-left:24px">${esc(c.items.slice(0, 5).join(', '))}${c.items.length > 5 ? '…' : ''}</div>` : ''}</div>`).join('')}`, { ic: 'shield' })}
  <div class="stack">${card('Migration from the spreadsheets', `<p class="muted" style="margin-bottom:10px">Sales records move from two spreadsheets, are reconciled, then the sheets are retired (Section 8.3). Cleaning rules applied on import: multiple plots in one cell (<code>20 &amp; 25</code>) become one plot each; amounts and dates become numbers and dates; the <code>p:</code> phone prefix is stripped; each plan gets one opening payment for the amount paid to date.</p><div class="row wrap"><button class="btn" data-act="mig.plots">1 · Land allocation database</button><button class="btn" data-act="mig.sales">2 · Client payment tracker</button><button class="btn" data-act="mig.recon">Reconciliation report</button></div>`, { ic: 'layers' })}${card('Import and export', `<div class="row wrap"><button class="btn" data-act="adm.importclients">${icon('upload', 'sm')} Import clients (CSV)</button><button class="btn" data-act="adm.zoho">${icon('upload', 'sm')} Import from Zoho Projects</button><button class="btn" data-act="adm.export">${icon('download', 'sm')} Export a table</button><button class="btn" data-act="adm.backup">${icon('download', 'sm')} Full backup (JSON)</button><button class="btn" data-act="adm.restore">${icon('upload', 'sm')} Restore backup</button><button class="btn" data-act="slack.import">${icon('chat', 'sm')} Import Slack history</button><button class="btn" data-act="adm.merge">${icon('copy', 'sm')} Merge duplicate clients</button></div>`, { ic: 'upload' })}</div></div><div style="margin-top:16px">${table({ id: 'bin', title: 'Recycle bin', rows: () => bin, export: false, empty: 'The recycle bin is empty.', ps: 8, cols: [{ k: 'c', l: 'Type', r: b => `<span class="tag">${esc(b.c)}</span>` }, { k: 'name', l: 'Record' }, { k: 'at', l: 'Deleted', r: b => fmtDT(b.at), sv: b => b.at }, { k: 'by', l: 'By', r: b => esc(userName(b.by)) }, { k: 'a', l: '', r: b => can('data.admin') ? `<button class="btn sm" data-act="bin.restore" data-id="${esc(b.id)}">Restore</button><button class="btn sm danger" data-act="bin.purge" data-id="${esc(b.id)}">Delete forever</button>` : '' }] })}</div>`;
}
ACT['bin.restore'] = el => { const [c, id] = el.dataset.id.split('|'); DB.restore(c, id); toast('Restored'); render(); };
ACT['bin.purge'] = el => confirmDlg('Delete this record permanently? This is logged and cannot be undone.', () => { const [c, id] = el.dataset.id.split('|'); DB.purge(c, id); render(); }, { danger: true, yes: 'Delete forever' });
ACT['adm.export'] = () => openForm({ title: 'Export a table', fields: [{ n: 'c', l: 'Data set', t: 'select', req: true, blank: false, o: ['clients', 'leads', 'plots', 'sales', 'payments', 'invoices', 'journals', 'employees', 'tasks', 'tickets', 'realtors', 'audit'] }, { n: 'f', l: 'Format', t: 'select', blank: false, o: [['csv', 'CSV'], ['xlsx', 'Excel'], ['json', 'JSON']] }], vals: { f: 'csv' }, submit: 'Export', onSubmit: v => { const rows = DB.q(v.c).map(r => { const o = {}; Object.entries(r).forEach(([k, x]) => { o[k] = typeof x === 'object' ? JSON.stringify(x) : x; }); return o; }); const keys = uniq(rows.flatMap(r => Object.keys(r))); if (v.f === 'json') { download(v.c + '-' + today() + '.json', JSON.stringify(DB.q(v.c), null, 2), 'application/json'); audit('export', 'export', v.c, rows.length + ' rows as json'); } else exportRows(v.c, keys.map(k => ({ l: k, x: r => r[k] })), rows, v.f); } });
ACT['adm.backup'] = () => { audit('export', 'backup', 'full', 'Full backup downloaded'); download('triop-backup-' + today() + '.json', JSON.stringify(DB.d), 'application/json'); toast('Backup downloaded. Keep it somewhere safe.'); };
ACT['adm.restore'] = () => openForm({ title: 'Restore a backup', fields: [{ n: 'file', l: 'Backup file (JSON)', t: 'file', accept: 'application/json', req: true }, { n: 'w', t: 'html', html: '<div class="alert bad">This replaces all data in this browser with the backup.</div>' }], submit: 'Restore', onSubmit: v => { try { const d = JSON.parse(atob(v.file.split(',')[1].replace(/-/g, '+').replace(/_/g, '/'))); if (!d.users || !d.companies) throw new Error('This does not look like a Tri-OP backup.'); DB.d = d; DB.flush(); applyRoleOverrides(); toast('Backup restored'); render(); } catch (e) { toast('Could not read that file: ' + e.message, 'bad'); return false; } } });
ACT['adm.importclients'] = () => importDialog({ title: 'Import clients', cols: ['name', 'phone', 'email', 'address', 'officer_email'], example: 'Ada Obi,08031234567,ada@mail.example,12 Allen Ave Ikeja,bayo.ogunleye@triconna.example', validate: r => { if (!r.name || !r.phone) return { err: 'Name and phone are required' }; const dup = DB.q('clients').find(c => phoneNorm(c.phone) === phoneNorm(r.phone)); if (dup) return { err: 'Duplicate of ' + dup.name }; const off = DB.d.users.find(u => u.email === (r.officer_email || '').toLowerCase()); return { rec: { name: r.name, phone: phoneNorm(r.phone), email: r.email || '', address: r.address || '', kyc: [{ name: 'ID card', ok: false }, { name: 'Proof of address', ok: false }, { name: 'Passport photo', ok: false }], officer: off ? off.id : salesOfficers()[0]?.id, source: 'Import', created: Date.now() } }; }, commit: recs => recs.forEach(r => DB.add('clients', r)) });
ACT['adm.merge'] = () => { const ph = {}; DB.q('clients').forEach(c => { const k = phoneNorm(c.phone); (ph[k] = ph[k] || []).push(c); }); const groups = Object.values(ph).filter(l => l.length > 1); openForm({ title: 'Merge client records', fields: [{ n: 'keep', l: 'Keep this client', t: 'select', req: true, reform: true, o: DB.q('clients').map(c => [c.id, c.name + ' · ' + c.phone]) }, { n: 'merge', l: 'Merge these into it', t: 'multi', req: true, o: v => DB.q('clients').filter(c => c.id !== v.keep).map(c => [c.id, c.name + ' · ' + c.phone]), hint: groups.length ? 'Duplicates found: ' + groups.map(g => g.map(c => c.name).join(' / ')).join('; ') : 'No duplicate phone numbers found.' }], submit: 'Merge', onSubmit: v => { v.merge.forEach(id => { ['sales', 'payments', 'tickets', 'interactions'].forEach(col => DB.q(col).filter(r => r.clientId === id).forEach(r => DB.set(col, r.id, { clientId: v.keep }, { quiet: true }))); DB.q('plots').filter(p => p.clientId === id).forEach(p => DB.set('plots', p.id, { clientId: v.keep }, { quiet: true })); DB.del('clients', id); }); audit('merge', 'clients', v.keep, 'Merged ' + v.merge.length + ' records'); toast('Merged. The old records are in the recycle bin.'); render(); } }); };
ACT['slack.import'] = () => openForm({ title: 'Import Slack history', fields: [{ n: 'ch', l: 'Into channel', t: 'select', req: true, o: DB.q('channels').filter(c => c.type !== 'dm').map(c => [c.id, c.name]) }, { n: 'file', l: 'Slack channel export (JSON array of messages)', t: 'file', accept: 'application/json', req: true, hint: 'Each message: { "user": "Name", "text": "…", "ts": 1700000000 }' }], onSubmit: v => { try { const arr = JSON.parse(atob(v.file.split(',')[1])); let n = 0; arr.filter(m => m.text).forEach(m => { const u = coUsers().find(x => x.name === m.user || x.email === m.user_email); DB.add('messages', { ch: v.ch, by: u ? u.id : SESS.uid, text: (u ? '' : '[' + (m.user || 'Slack') + '] ') + m.text, ts: Math.round(+m.ts * 1000) || Date.now(), imported: true }, { quiet: true }); n++; }); audit('import', 'messages', v.ch, n + ' Slack messages'); toast(n + ' messages imported'); render(); } catch (e) { toast('Could not read the file: ' + e.message, 'bad'); return false; } } });

/* migration importers (Section 8.3) */
const PLAN_MONTHS = s => { const x = String(s || '').toLowerCase(); if (/outright|full/.test(x)) return 0; const m = x.match(/(\d+)/); return m ? +m[1] : 0; };
ACT['mig.plots'] = () => importDialog({ title: 'Migrate the Land Allocation Database', cols: ['estate', 'plot', 'size', 'status', 'owner', 'price', 'documentation'], example: 'Velcrest,20 & 25,450,Sold,Ada Obi,2900000,Pending', validate: r => { const est = DB.q('estates').find(e => e.name.toLowerCase() === (r.estate || '').trim().toLowerCase()); if (!est) return { err: 'Estate "' + r.estate + '" does not exist. Create it first.' }; const nos = String(r.plot || '').split(/\s*(?:&|,|;|\band\b)\s*/i).map(x => x.trim()).filter(Boolean); if (!nos.length) return { err: 'No plot number' }; const st = String(r.status || '').toLowerCase(); if (!/available|reserved|sold/.test(st)) return { err: 'Status must be Available, Reserved or Sold' }; if (/sold|reserved/.test(st) && !r.owner) return { err: 'Sold or reserved plots need an owner' }; return { rec: { est, nos, st, owner: (r.owner || '').trim(), price: num0(r.price), size: num0(r.size), docs: r.documentation || '' } }; }, commit: recs => { recs.forEach(r => r.nos.forEach(no => { let p = DB.q('plots').find(x => x.estate === r.est.id && x.no === no); const st = /sold/.test(r.st) ? 'allocated' : /reserved/.test(r.st) ? 'reserved' : 'available'; const cl = r.owner ? (DB.q('clients').find(c => c.name.toLowerCase() === r.owner.toLowerCase()) || DB.add('clients', { name: r.owner, phone: '', email: '', address: '', kyc: [], officer: salesOfficers()[0]?.id, source: 'Migration', created: Date.now() }, { quiet: true })) : null; if (!p) p = DB.add('plots', { estate: r.est.id, block: '', no, sqm: r.size, price: r.price || r.est.sizes[0].price, status: 'available', log: [], docs: null, survey: '' }, { quiet: true }); DB.set('plots', p.id, { status: st, clientId: cl ? cl.id : '', price: r.price || p.price, sqm: r.size || p.sqm, migrated: true, log: (p.log || []).concat([{ ts: Date.now(), from: p.status, to: st, by: SESS.uid, note: 'Migrated from allocation sheet' }]), docs: /document/i.test(r.docs) ? { survey: { s: 'Issued', date: today() }, deed: { s: 'Issued', date: today() }, cofo: { s: 'Issued', date: today() } } : p.docs }, { quiet: true }); })); toast(recs.length + ' rows migrated. Run the reconciliation report next.'); } });
ACT['mig.sales'] = () => importDialog({ title: 'Migrate the TR Client Payment Tracker', cols: ['client', 'phone', 'email', 'estate', 'plots', 'plan', 'total', 'paid', 'realtor', 'source'], example: 'Ada Obi,p:08031234567,ada@mail.example,Velcrest,20 & 25,6 months,5800000,2000000,,Instagram', validate: r => { const est = DB.q('estates').find(e => e.name.toLowerCase() === (r.estate || '').trim().toLowerCase()); if (!est) return { err: 'Estate "' + r.estate + '" does not exist' }; const phone = phoneNorm(r.phone); if (!r.client || phone.length < 8) return { err: 'Client name and a valid phone number are required' }; const nos = String(r.plots || '').split(/\s*(?:&|,|;|\band\b)\s*/i).map(x => x.trim()).filter(Boolean); const plots = nos.map(n => DB.q('plots').find(p => p.estate === est.id && p.no === n)); if (!nos.length || plots.some(p => !p)) return { err: 'Plot not found in the allocation data: ' + nos.filter((n, i) => !plots[i]).join(', ') + '. Migrate the allocation sheet first.' }; const taken = plots.find(p => activeSaleOfPlot(p.id)); if (taken) return { err: plotLabel(taken) + ' already belongs to a sale' }; const total = num0(r.total), paid = num0(r.paid); if (total <= 0) return { err: 'Total must be above zero' }; if (paid > total) return { err: 'Paid is more than the total' }; return { rec: { est, plots, name: r.client.trim(), phone, email: r.email || '', months: PLAN_MONTHS(r.plan), total, paid, realtor: (r.realtor || '').trim(), source: r.source || 'Migration' } }; }, commit: recs => { let open = 0; recs.forEach(r => { let cl = DB.q('clients').find(c => phoneNorm(c.phone) === r.phone) || DB.q('clients').find(c => !c.phone && c.name.toLowerCase() === r.name.toLowerCase()); if (cl && !cl.phone) cl = DB.set('clients', cl.id, { phone: r.phone, email: r.email || cl.email }, { quiet: true }); cl = cl || DB.add('clients', { name: r.name, phone: r.phone, email: r.email, address: '', kyc: [{ name: 'ID card', ok: false }, { name: 'Proof of address', ok: false }, { name: 'Passport photo', ok: false }], officer: salesOfficers()[0]?.id, source: r.source, created: Date.now() }, { quiet: true }); const plan = r.est.plans.find(p => p.months === r.months) || r.est.plans[0]; const rl = r.realtor && DB.q('realtors').find(x => x.name.toLowerCase() === r.realtor.toLowerCase()); const rem = r.total - r.paid; const sch = [{ no: 0, label: 'Opening payment (migrated)', due: today(), amount: r.paid, paid: r.paid }]; if (rem > 0) { const n = r.months || 1; const each = Math.floor(rem / n / 100) * 100; for (let i = 1; i <= n; i++) sch.push({ no: i, label: 'Instalment ' + i + ' of ' + n, due: addMonths(today(), i), amount: i === n ? rem - each * (n - 1) : each, paid: 0 }); } const sale = DB.add('sales', { no: 'SL-' + today().slice(0, 4) + '-' + String(DB.seq('sale')).padStart(4, '0'), clientId: cl.id, estateId: r.est.id, plotIds: r.plots.map(p => p.id), planId: plan.id, planName: plan.name + ' (migrated)', months: r.months, base: r.total, total: r.total, deposit: r.paid, schedule: sch, paid: r.paid, officer: cl.officer, realtorId: rl ? rl.id : '', date: today(), status: r.paid >= r.total ? 'completed' : 'active', migrated: true }, { quiet: true }); if (r.paid > 0) DB.add('payments', { saleId: sale.id, clientId: cl.id, amount: r.paid, method: 'Migrated opening balance', channel: 'migration', date: today(), status: 'confirmed', receiptNo: 'MIG-' + String(DB.seq('mig')).padStart(5, '0'), confirmations: [], recordedBy: 'migration', ts: Date.now(), confirmedAt: Date.now() }, { quiet: true }); r.plots.forEach(p => { DB.set('plots', p.id, { status: r.paid >= r.total ? 'paid' : 'allocated', clientId: cl.id, saleId: sale.id, reservedUntil: '', log: (p.log || []).concat([{ ts: Date.now(), from: p.status, to: r.paid >= r.total ? 'paid' : 'allocated', by: SESS.uid, note: 'Migrated sale ' + sale.no }]) }, { quiet: true }); }); open += rem; }); if (open > 0) { try { postJournal({ date: today(), memo: 'Opening balances migrated from payment tracker (' + recs.length + ' sales)', lines: [{ acct: '1100', dr: open }, { acct: '3100', cr: open }], source: 'migration', quiet: true }); } catch (e) { toast(e.message, 'bad'); } } audit('import', 'migration', 'sales', recs.length + ' sales, opening balance ' + money(open)); toast(recs.length + ' sales migrated. Finance signs off the opening balances.'); } });
ACT['mig.recon'] = () => {
  const sold = DB.q('plots').filter(p => ['allocated', 'paid', 'documented'].includes(p.status)); const noSale = sold.filter(p => !activeSaleOfPlot(p.id)); const orphan = DB.q('sales').filter(s => !['revoked', 'expired'].includes(s.status) && s.plotIds.some(i => !['allocated', 'paid', 'documented', 'reserved'].includes(DB.get('plots', i)?.status)));
  const byE = DB.q('estates').map(e => { const ps = DB.q('plots').filter(p => p.estate === e.id); const ss = DB.q('sales').filter(s => s.estateId === e.id && !['revoked', 'expired'].includes(s.status)); return { e: e.name, n: ps.length, av: ps.filter(p => p.status === 'available').length, so: ps.filter(p => ['allocated', 'paid', 'documented'].includes(p.status)).length, v: sum(ss, s => s.total), p: sum(ss, s => s.paid), b: sum(ss, s => saleBalance(s)) }; });
  openModal({ title: 'Reconciliation report', xl: true, live: false, body: `<div class="grid g3" style="margin-bottom:14px">${tile({ ic: 'estate', title: 'Sold plots', value: sold.length, sub: noSale.length + ' without a matching sale' })}${tile({ cls: 'tea', ic: 'receipt', title: 'Active sales', value: DB.q('sales').filter(s => !['revoked', 'expired'].includes(s.status)).length, sub: orphan.length + ' with plot mismatch' })}${tile({ cls: 'dark', ic: 'scale', title: 'Total balance', value: moneyShort(sum(byE, x => x.b)) })}</div><table class="tbl"><thead><tr><th>Estate</th><th class="num">Plots</th><th class="num">Available</th><th class="num">Sold</th><th class="num">Contract value</th><th class="num">Paid</th><th class="num">Balance</th></tr></thead><tbody>${byE.map(x => `<tr><td>${esc(x.e)}</td><td class="num">${x.n}</td><td class="num">${x.av}</td><td class="num">${x.so}</td><td class="num">${money(x.v)}</td><td class="num">${money(x.p)}</td><td class="num">${money(x.b)}</td></tr>`).join('')}</tbody></table>${noSale.length ? `<div class="alert" style="margin-top:12px">${icon('warn', 'sm')}<span>Sold plots without a client and price in the payment tracker: ${esc(noSale.slice(0, 8).map(plotLabel).join(', '))}</span></div>` : ''}`, foot: `<button class="btn" data-act="ov.close">Close</button><button class="btn primary" data-act="recon.print">Print or save PDF</button>` });
};
ACT['recon.print'] = () => printHtml('<div class="doc"><div class="lh"><b>Migration reconciliation</b><span>' + esc(company().name) + ' · ' + fmtDate(today()) + '</span></div>' + $('.modal .mb').innerHTML + '</div>');

