function admFlows() {
  const so = DB.q('signoffs');
  return `<div class="alert info" style="margin-bottom:14px">${icon('check', 'sm')}<span><b>Section 9 gate.</b> Each P1 flow is prototyped here with real data. Walk it with at least 5 staff, record the testers, and Triconna signs it off before build. Open a step to run it live.</span></div><div class="grid g2">${FLOWS.map(f => { const rec = so.filter(x => x.flow === f.id).sort(by(x => x.ts, -1))[0]; const testers = rec ? rec.testers.length : 0; return card(esc(f.name), `<ol style="margin:0 0 12px;padding-left:18px">${f.steps.map((t, i) => `<li style="margin:4px 0"><a href="#/${f.go[i]}">${esc(t)}</a></li>`).join('')}</ol><div class="row">${rec ? spill(rec.signed ? 'Signed off' : testers + ' of 5 testers', rec.signed ? 'ok' : 'warn') : spill('Not tested', 'mute')}<span class="sp"></span><button class="btn sm" data-act="flow.rec" data-id="${f.id}">Record test session</button>${rec && !rec.signed && testers >= 5 && (isExec() || can('admin.config')) ? `<button class="btn sm primary" data-act="flow.sign" data-id="${f.id}">Sign off</button>` : ''}</div>`, { ic: 'share' }); }).join('')}</div><div style="margin-top:16px">${card('Design system', `<p class="muted" style="margin-bottom:10px">Figma design system shared with Tri-Pay: colours, type, components and states.</p><a class="btn" href="#/admin/design">Open the design system</a>`, { ic: 'layers' })}</div>`;
}
ACT['flow.rec'] = el => { const f = FLOWS.find(x => x.id === el.dataset.id); openForm({ title: 'Test session · ' + esc(f.name), fields: [{ n: 'testers', l: 'Staff who tested it', t: 'multi', req: true, o: coUsers().filter(u => u.role !== 'auditor').map(u => [u.id, u.name.split(' ')[0] + ' ' + (u.name.split(' ')[1] || '')[0] + '.']) }, { n: 'notes', l: 'What did they find hard?', t: 'textarea' }], onSubmit: v => { const prev = DB.q('signoffs').find(x => x.flow === f.id); const all = uniq((prev ? prev.testers : []).concat(v.testers)); if (prev) DB.set('signoffs', prev.id, { testers: all, notes: ((prev.notes || '') + '\n' + (v.notes || '')).trim(), ts: Date.now() }); else DB.add('signoffs', { flow: f.id, testers: all, notes: v.notes || '', signed: false, ts: Date.now() }); toast(all.length + ' testers recorded'); render(); } }); };
ACT['flow.sign'] = el => confirmDlg('Sign off this flow for build? This is logged.', () => { const r = DB.q('signoffs').find(x => x.flow === el.dataset.id); DB.set('signoffs', r.id, { signed: true, signedBy: SESS.uid, signedAt: Date.now() }, { action: 'signoff' }); render(); }, { yes: 'Sign off' });
